export type SubmitApplicationBody = {
  type: SubmitApplicationBodyType;
  ownerFirstName: string;
  ownerLastName: string;
  businessName: string;
  email?: string;
  phone?: string;
  ein?: string;
  /** Nine digits; encrypted at rest and never returned in plaintext */
  ownerSsn?: string;
  ownerDob?: string;
  businessType?: SubmitApplicationBodyBusinessType;
  annualRevenue?: number;
  industry?: string;
  industryDetail?: string;
  /** Exact stated monthly revenue; do not submit a bucket ceiling. */
  monthlyRevenueStated?: number;
  timeInBusinessMonths?: number;
  industryExperienceMonths?: number;
  /**
     * Optional business start month and year in MM/YYYY format
     * @pattern ^(0[1-9]|1[0-2])/[0-9]{4}$
     */
  businessStartDate?: string;
  yearsUnderCurrentOwnership?: number;
  businessDescription?: string;
  estCreditScore?: SubmitApplicationBodyEstCreditScore;
  timelineFundsNeeded?: string;
  secondaryOwnerName?: string;
  secondaryOwnerEmail?: string;
  secondaryOwnerAddress?: string;
  /** Nine digits; encrypted at rest and never returned in plaintext */
  secondaryOwnerSsn?: string;
  secondaryOwnerDob?: string;
  secondaryOwnerOwnershipPct?: number;
  secondaryOwnerCell?: string;
  secondaryOwnerEstCreditScore?: SubmitApplicationBodySecondaryOwnerEstCreditScore;
  /** Equipment applications only */
  yearMakeModel?: string;
  /** Equipment applications only */
  trucksInFleet?: number;
  /** Equipment applications only */
  downPaymentAmount?: number;
  hasFinancialStatements?: boolean;
  hasFactoring?: boolean;
  hasCollateral?: boolean;
  consentCreditPull: boolean;
  consentTerms: boolean;
  /** Optional SMS consent; omitted and false are both opt-out. */
  smsConsent?: boolean;
  signatureMethod: SubmitApplicationBodySignatureMethod;
  /**
     * Typed legal name or base64 image data URL for a drawn signature
     * @maxLength 500000
     */
  signatureData: string;
  equipmentDescription?: string;
  /** Optional applicant-reported equipment category; never inferred */
  equipmentCategory?: SubmitApplicationBodyEquipmentCategory;
  /** Optional vendor/dealer name */
  vendorName?: string;
  /** Optional applicant-reported homeownership; never inferred */
  isHomeowner?: boolean;
  bankStatements?: Blob[];
};

